# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KUBÂ\'DAN MEDİNE\'YE VARIŞ VE ENSAR\'IN COŞKULU KARŞILAMASI</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Kubâ ve Ranuna Vadisi</text>\n  <text x="38" y="98" font-size="11" fill="#334155">• Kubâ\'da İslam\'ın ilk mescidi olan</text>\n  <text x="38" y="114" font-size="11" font-weight="bold" fill="#1e40af">  Kubâ Mescidi inşa edildi.</text>\n  <text x="38" y="138" font-size="11" fill="#334155">• Hz. Ali emanetleri verip Kubâ\'da</text>\n  <text x="38" y="154" font-size="11" fill="#334155">  Hz. Peygamber\'e yetişti.</text>\n  <text x="38" y="178" font-size="11" fill="#334155">• Cuma günü Ranuna Vadisi\'nde</text>\n  <text x="38" y="194" font-size="11" font-weight="bold" fill="#1e40af">  ilk Cuma namazı kılındı.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Medine\'ye Giriş ve Kusvâ</text>\n  <text x="258" y="98" font-size="11" fill="#334155">• Ensar (Medineli Müslümanlar)</text>\n  <text x="258" y="114" font-size="11" fill="#334155">  büyük bir sevgiyle karşıladı.</text>\n  <text x="258" y="138" font-size="11" fill="#334155">• Devesi Kusvâ serbest bırakıldı;</text>\n  <text x="258" y="154" font-size="11" fill="#334155">  Sehl ve Süheyl adlı iki yetime</text>\n  <text x="258" y="170" font-size="11" fill="#334155">  ait arsaya çöktü.</text>\n  <text x="258" y="194" font-size="11" font-weight="bold" fill="#166534">• Arsa bedeli ödenerek Mescid-i</text>\n  <text x="258" y="210" font-size="11" font-weight="bold" fill="#166534">  Nebevî için satın alındı.</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Mihmandâr-ı Nebî</text>\n  <text x="478" y="98" font-size="11" fill="#334155">• Mescid-i Nebevî inşa edilene</text>\n  <text x="478" y="114" font-size="11" fill="#334155">  kadar Hz. Peygamber 7 ay</text>\n  <text x="478" y="130" font-size="11" font-weight="bold" fill="#92400e">  Ebû Eyyûb el-Ensârî\'nin</text>\n  <text x="478" y="146" font-size="11" fill="#334155">  (Halid bin Zeyd) evinde kaldı.</text>\n  <text x="478" y="172" font-size="11" fill="#334155">• Yesrib şehri bu kutlu gelişle</text>\n  <text x="478" y="190" font-size="11" font-weight="bold" fill="#92400e">  Medînetü\'n-Nebî (Medine)</text>\n  <text x="478" y="206" font-size="11" fill="#334155">  adını aldı.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HİCRET\'İN İSLAM TARİHİNDEKİ SONUÇLARI VE MUHACİR-ENSAR KARDEŞLİĞİ</text>\n  <rect x="28" y="48" width="310" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="183" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Muhacir ve Ensar Kardeşliği (Muâhât)</text>\n  <text x="44" y="100" font-size="11.5" font-weight="bold" fill="#1e40af">• Muhacir:</text>\n  <text x="54" y="118" font-size="11" fill="#334155">İnançları uğruna Mekke\'deki evlerini ve</text>\n  <text x="54" y="134" font-size="11" fill="#334155">mallarını bırakıp Medine\'ye göç edenler.</text>\n  <text x="44" y="160" font-size="11.5" font-weight="bold" fill="#1e40af">• Ensar (Yardım Edenler):</text>\n  <text x="54" y="178" font-size="11" fill="#334155">Mekkeli muhacirlere kucak açıp evlerini</text>\n  <text x="54" y="194" font-size="11" fill="#334155">ve imkânlarını paylaşan Medineli müminler.</text>\n  <text x="44" y="218" font-size="11" font-weight="bold" fill="#1d4ed8">* Muâhât ile her Muhacir bir Ensar ile kardeş ilan edildi.</text>\n  <rect x="362" y="48" width="310" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Hicret\'in Temel Sonuçları (622)</text>\n  <text x="378" y="100" font-size="11" fill="#334155">1. Müslümanlar müşriklerin baskı ve zulmünden</text>\n  <text x="378" y="116" font-size="11" fill="#334155">   kurtularak dinlerini özgürce yaşama imkânı buldu.</text>\n  <text x="378" y="140" font-size="11" fill="#334155">2. Medine İslam Devleti\'nin temelleri atıldı ve</text>\n  <text x="378" y="156" font-size="11" fill="#334155">   İslam toplumsal bir güç hâline geldi.</text>\n  <text x="378" y="180" font-size="11" fill="#334155">3. Mescid-i Nebevî ve Suffe ile ilim merkezi kuruldu.</text>\n  <text x="378" y="204" font-size="11" fill="#334155">4. Hz. Ömer döneminde Hicret olayı Hicrî takvimin</text>\n  <text x="378" y="220" font-size="11" font-weight="bold" fill="#166534">   başlangıcı (1. yıl) olarak kabul edildi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1. ÜNİTE KRONOLOJİK ÖZETİ: HİCRETTEN ÖNCE PEYGAMBERİMİZ</text>\n  <rect x="20" y="50" width="152" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="96" y="74" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b91c1c">1. Hüzün Yılı ve Taif</text>\n  <text x="30" y="98" font-size="10.5" fill="#334155">• Boykot sonrası</text>\n  <text x="30" y="114" font-size="10.5" fill="#334155">  Ebû Tâlib ve Hz.</text>\n  <text x="30" y="130" font-size="10.5" fill="#334155">  Hatice\'nin vefatı</text>\n  <text x="30" y="146" font-size="10.5" fill="#334155">  (Senetü\'l-Hüzün).</text>\n  <text x="30" y="170" font-size="10.5" fill="#334155">• Taif yolculuğu,</text>\n  <text x="30" y="186" font-size="10.5" fill="#334155">  Hz. Zeyd ve Addâs\'ın</text>\n  <text x="30" y="202" font-size="10.5" fill="#334155">  Müslüman oluşu.</text>\n  <rect x="188" y="50" width="152" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="264" y="74" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">2. İsrâ ve Miraç</text>\n  <text x="198" y="98" font-size="10.5" fill="#334155">• İsrâ: Mescid-i</text>\n  <text x="198" y="114" font-size="10.5" fill="#334155">  Haram\'dan Mescid-i</text>\n  <text x="198" y="130" font-size="10.5" fill="#334155">  Aksâ\'ya gece yürüyüşü.</text>\n  <text x="198" y="154" font-size="10.5" fill="#334155">• Miraç: Göklere</text>\n  <text x="198" y="170" font-size="10.5" fill="#334155">  yükseliş ve 3 hediye</text>\n  <text x="198" y="186" font-size="10.5" fill="#334155">  (5 vakit namaz,</text>\n  <text x="198" y="202" font-size="10.5" fill="#334155">  Âmenerrasûlü, müjde).</text>\n  <rect x="356" y="50" width="152" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="432" y="74" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#a16207">3. Akabe Biatları</text>\n  <text x="366" y="98" font-size="10.5" fill="#334155">• I. Akabe (621):</text>\n  <text x="366" y="114" font-size="10.5" fill="#334155">  12 kişi; Mus\'ab bin</text>\n  <text x="366" y="130" font-size="10.5" fill="#334155">  Umeyr ilk öğretmen.</text>\n  <text x="366" y="154" font-size="10.5" fill="#334155">• II. Akabe (622):</text>\n  <text x="366" y="170" font-size="10.5" fill="#334155">  75 kişi; Hz. Peygamber\'i</text>\n  <text x="366" y="186" font-size="10.5" fill="#334155">  Medine\'ye davet ve</text>\n  <text x="366" y="202" font-size="10.5" fill="#334155">  koruma sözü.</text>\n  <rect x="524" y="50" width="156" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="602" y="74" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#15803d">4. Hicret (622)</text>\n  <text x="534" y="98" font-size="10.5" fill="#334155">• Dârünnedve suikast</text>\n  <text x="534" y="114" font-size="10.5" fill="#334155">  planı ve Hz. Ali\'nin</text>\n  <text x="534" y="130" font-size="10.5" fill="#334155">  emanetler için kalışı.</text>\n  <text x="534" y="154" font-size="10.5" fill="#334155">• Hz. Ebû Bekir ile</text>\n  <text x="534" y="170" font-size="10.5" fill="#334155">  Sevr Mağarası, Kubâ</text>\n  <text x="534" y="186" font-size="10.5" fill="#334155">  Mescidi, İlk Cuma</text>\n  <text x="534" y="202" font-size="10.5" fill="#334155">  ve Medine\'ye varış.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
